-- 더케어타임즈 '교육' 섹션: 정부·공공기관 보도자료(교육부 10월 12~27일)를 바탕으로 새로 쓴 시작용 기사 10건 — 승인대기(in_review)
-- Supabase SQL 에디터에서 실행. 여러 번 실행해도 된다 (같은 제목 기사는 건너뛴다)
--   · 카테고리는 이름('교육')으로 찾는다. 이 매체에 '교육' 카테고리가 없으면 기사가 들어가지 않으니 맨 아래 확인용 select 로 확인한다
--   · 작성 기자: 김경석 (김경석 계정이 있으면 그 계정, 없으면 첫 편집장·관리자 계정에 기자명만 김경석)
--   · 사진: 저장소의 /sites/thecaretimes/photos/ct-edu-1~10.webp (위키미디어 공용 공개 라이선스, 배포가 끝난 뒤에 보인다)
--   · 기사마다 AI 메모(확인할 점·원문 주소·이용 조건)가 붙는다. AI 활용 표시는 매체 설정이 자동으로 붙인다

with ctx as (
  select o.id as outlet_id,
         coalesce(
           (select p.id from profiles p where trim(p.full_name) = '김경석' order by (p.outlet_id = o.id) desc, p.created_at limit 1),
           (select p.id from profiles p where p.outlet_id = o.id and p.role in ('admin', 'editor') order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.domain = 'thecaretimes.net'
)
insert into articles (outlet_id, category_id, author_id, title, body, excerpt, thumbnail_url, status, published_at, tags)
select ctx.outlet_id, c.id, ctx.author_id, v.title,
       replace(v.body, '@@BYLINE@@', '[더케어타임즈=김경석 기자]'),
       v.excerpt, v.thumb, 'in_review', v.published_at, v.tags
from ctx
cross join (values
  ('수능 11월 19일 시행…1,312개 시험장서 55만여 명 응시', '<p>@@BYLINE@@&nbsp;2027학년도 대학수학능력시험(수능)이 11월 19일(목) 전국 85개 시험지구 1,312개 시험장에서 치러진다. 교육부는 20일 국무회의에 ‘2027학년도 대학수학능력시험 당일 안정적 시험 시행을 위한 지원대책’을 보고했다고 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-1.webp" alt="2018학년도 수능에서 쓰인 수험생용 컴퓨터용 사인펜과 샤프"><p><em>▲ 2018학년도 수능에서 쓰인 수험생용 컴퓨터용 사인펜과 샤프(2017년 11월 촬영한 자료사진, 올해 시험 장면 아님) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>시험은 이날 오전 8시 40분에 시작해 오후 5시 45분(일반 수험생 기준)까지 이어진다. 시험편의 제공 대상자(중증 시각장애)를 포함하면 종료 시각은 오후 9시 48분이다. 응시 예정자는 55만 1,864명으로, 지난해보다 2,310명 줄었다.</p><p>정부는 수험생이 교통 혼잡 때문에 늦지 않도록 관공서와 기업체에 출근 시간을 오전 10시 이후로 조정해 달라고 요청한다. 수험생 등교 시간대인 오전 6시부터 8시 10분 사이에는 수도권 지하철 운행 대수를 늘리고, 경찰서 등 행정기관의 비상 수송 차량을 수험생 이동 경로에 배치한다. 시험장 200m 앞부터는 차량 출입이 통제돼, 자가용을 이용하는 수험생은 200m 전방에서 내려 걸어가야 한다.</p><p>3교시 영어영역 듣기평가(오후 1시 10분~1시 35분, 25분간)에는 항공기·헬리콥터 이착륙 시간을 조정하고, 포 사격과 전차 이동 같은 군사훈련을 잠시 멈춘다. 듣기평가 시간이 아닐 때도 시험장 주변을 지나는 버스·열차는 서행하고 경적 사용을 자제하며, 주변 행사장과 공사장의 생활소음도 최대한 줄여 달라고 당부했다.</p><p>수험생은 11월 13일(금)부터 기상청 누리집에서 시험장 날씨를 미리 확인할 수 있다. 시도는 도서·벽지 수험생 수송 대책과 제설 대책을 마련하고, 16개 시도교육청은 전체 시험장을 대상으로 안전 점검을 한다. 수능 당일에는 지진 상황을 상시 점검하고, 전체 시험장에 정보 전달 체계를 갖춰 지진이 나면 대처 요령에 따라 빠르게 대응하도록 한다.</p><p>문답지 보안도 강화한다. 교육부는 경찰청, 시도교육청과 함께 철저한 경비 체계를 마련하고, 모든 시험지구에 교육부 중앙협력관을 보내 문답지 관리를 지원한다.</p><p>최교진 교육부 장관은 “수험생 여러분이 그동안 갈고닦은 실력을 충분히 발휘할 수 있도록 모든 부처가 힘을 모아 최선을 다해 돕겠다”고 밝혔다. 수험생 유의사항은 추후 별도로 안내할 예정이다.</p>', '교육부가 수능 당일 교통 소통, 소음 방지, 자연재해 대비, 문답지 보안을 위한 정부 지원대책을 국무회의에 보고했다.', '/sites/thecaretimes/photos/ct-edu-1.webp', '2026-10-20T14:20:00+09:00'::timestamptz, array['수능', '2027학년도', '대학입시', '교육부', '수험생']::text[]),
  ('어린이집·유치원 입소·입학 신청 11월 2일 시작…‘찜하기’ 도입', '<p>@@BYLINE@@&nbsp;2027학년도 신학기 어린이집 입소와 유치원 입학 신청이 11월 2일(월)부터 시작된다. 교육부는 15일 신청 과정을 더 편리하게 하도록 관련 서비스를 대폭 개선한다고 밝혔다. 어린이집 입소와 유치원 입학 신청 창구는 2024년 ‘유보통합포털’로 하나로 합쳐졌고, 이번 개편은 실제 신청 과정에서 학부모와 기관이 겪는 어려움을 줄이는 데 중점을 뒀다.</p><img src="/sites/thecaretimes/photos/ct-edu-2.webp" alt="유치원 출입구 모습"><p><em>▲ 유치원 출입구 자료사진(2017년 11월 촬영, 간판 글자는 흐림 처리) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>첫째는 선제적 알림이다. 신청 시기 전에 0~5세 자녀를 둔 학부모에게 입소·입학 관련 정보를 휴대전화 알림 서비스(복지멤버십)로 먼저 알려, 신청 일정이나 기관 검색 정보를 직접 찾아 확인해야 했던 불편을 줄인다.</p><p>둘째는 ‘찜하기’ 기능이다. 유보통합포털에서 관심 있는 어린이집과 유치원을 검색해 하나의 목록에 미리 저장하고, 그중 원하는 기관을 골라 바로 입소·입학을 신청할 수 있다. 어린이집과 유치원을 따로 찾아보고 신청해야 했던 번거로움을 덜기 위한 것이다.</p><p>셋째는 행정정보 연계다. 신청 때마다 직접 입력하던 자녀 정보는 행정정보를 연계해 가족 정보를 불러와 한 번에 등록한다. 가족관계증명서 등 자격 확인에 필요한 서류는 직접 발급받아 내는 대신 행정안전부의 공공 마이데이터로 받은 행정정보를 활용해 온라인으로 확인하거나 제출할 수 있다. 연계 대상 서류는 최대 20종(어린이집 6종, 유치원 14종)이다.</p><p>일정은 회원가입이 상시, 자녀 등록과 찜하기가 10월 28일(수), 입소·입학 신청이 11월 2일(월)부터다. 교육부는 동영상, 포스터, 리플릿을 만들어 대국민 누리집과 사회관계망서비스(SNS)로 신청 일정과 이용 방법을 알릴 계획이다.</p><p>강민규 교육부 영유아정책국장은 “이번 서비스 개선은 유치원과 어린이집 구분 없이 학부모가 한곳에서 보다 쉽고 편리하게 입소·입학 신청을 할 수 있도록 하는 데 중점을 두었다”며 “학부모와 어린이집·유치원 모두 현장에서 변화를 체감할 수 있는 안정적이고 편리한 서비스를 제공하겠다”고 말했다.</p>', '교육부가 2027학년도 어린이집·유치원 입소·입학 신청을 유보통합포털에서 선제 알림, 찜하기, 행정정보 연계로 더 쉽게 바꾼다.', '/sites/thecaretimes/photos/ct-edu-2.webp', '2026-10-21T10:15:00+09:00'::timestamptz, array['유보통합', '어린이집', '유치원', '입학신청', '영유아']::text[]),
  ('틈새돌봄 운영 기관, QR코드로 찾는다…소아과·육아센터에 포스터', '<p>@@BYLINE@@&nbsp;늦은 퇴근이나 휴일 근무로 어린이집·유치원 운영 시간 이후 돌봄이 필요한 학부모가 ‘틈새돌봄 운영 기관’을 더 쉽게 찾을 수 있도록 정부가 안내를 강화한다. 교육부는 19일 정보무늬(QR코드)가 담긴 안내문(리플릿)과 포스터를 만들어 영유아 학부모가 자주 찾는 장소에 붙이고, 관련 누리집을 고친다고 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-3.webp" alt="학교 건물 옆 놀이터"><p><em>▲ 학교 놀이터 자료사진(2019년 9월 촬영, 특정 틈새돌봄 기관과 무관) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>틈새돌봄 운영 기관은 야간연장 보육을 하는 어린이집과, 유치원·어린이집 가운데 거점형 돌봄기관을 말한다. 교육부에 따르면 8월 기준 거점형 돌봄기관은 162곳(유치원 76곳, 어린이집 86곳), 야간연장 어린이집은 7,398곳이다. 틈새돌봄에는 늦은 저녁, 주말, 휴일, 방학 시간대 돌봄이 포함된다.</p><p>안내문과 포스터에는 운영 기관 검색·신청 경로를 알려 주는 QR코드가 들어간다. 교육부는 소아청소년과 의원, 영유아 검진 지정 병의원, 육아종합지원센터, 어린이 도서관처럼 학부모가 자주 가는 곳에 게시해 자녀의 예방접종이나 진료 과정에서 자연스럽게 정보를 접하도록 한다는 계획이다.</p><p>영유아 학부모가 자주 접속하는 아이사랑 포털과 누리과정 포털 ‘방과후’의 첫 화면에서도 틈새돌봄 운영 기관 검색과 신청 방법을 바로 확인할 수 있게 누리집을 개선한다. 안내문과 포스터는 시도교육청과 지방자치단체 누리집에 올리고, 알림창(배너, 팝업 등)을 통한 ‘틈새돌봄 운영 기관 찾기’ 연결도 지원한다. 이를 활용하면 지역별 운영 기관 명단, 신청 자격, 이용 가능 시간을 확인할 수 있다.</p><p>2027년 2월부터는 카카오톡 유치원 입학 알림톡으로 틈새돌봄 정보 접속 주소(URL)를 안내하고, 2027년 하반기부터는 정부24의 국민비서·혜택알리미 서비스로 어린이집·유치원 틈새돌봄 알림서비스를 제공한다.</p><p>김정연 교육부 영유아지원관은 “정보를 찾지 못해 영유아 틈새돌봄을 이용하지 못하는 일이 없도록, 학부모님들이 생활 속에서 많이 접하는 통로를 활용해 적극적으로 정보를 안내하고자 했다”며 “자녀를 안심하고 맡길 수 있는 틈새돌봄 운영 기관을 계속 확대해 나가겠다”고 밝혔다.</p>', '교육부가 어린이집·유치원 틈새돌봄 운영 기관을 QR코드 안내문·포스터와 누리집, 알림톡으로 쉽게 찾도록 안내를 강화한다.', '/sites/thecaretimes/photos/ct-edu-3.webp', '2026-10-20T09:30:00+09:00'::timestamptz, array['틈새돌봄', '영유아', '유보통합', '야간연장보육', '돌봄']::text[]),
  ('유아 레벨테스트 금지 제도 점검 강화…12월부터 집중 점검', '<p>@@BYLINE@@&nbsp;교육부가 10월 1일 시행된 학원법 개정, 이른바 ‘유아 대상 레벨테스트 금지’ 제도가 현장에서 실제로 지켜지도록 점검과 조치를 강화한다. 교육부는 14일 보도참고자료에서 위반행위 점검·조치 강화, 시도교육청 세부기준 정비, 사후 관리 체계 구축을 중점 추진한다고 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-4.webp" alt="유치원 놀이터 전경"><p><em>▲ 유치원 놀이터 자료사진(2019년 9월 촬영, 특정 학원·기관과 무관) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>개정 학원법은 유아를 대상으로 한 모집·분반을 위한 시험·평가를 금지한다. 다만 유아의 발달 단계와 수준에 맞는 교육을 지원하기 위한 관찰·면담 방식의 진단행위는 예외로 허용한다.</p><p>교육부는 제도 시행 직후 2개월(10~11월)에는 학원·교습소와 학부모를 대상으로 레벨테스트 금지를 적극 알리되, 명백한 위반행위는 법령에 따라 조치한다. 유아 대상 모집과 분반이 몰리는 12월부터 이듬해 1월까지는 금지 이행 여부와 우회·편법 운영 현황을 집중 점검한다. 이를 위해 신고 접수 체계를 강화하고 신고포상금 제도를 활용한다. 신고포상금 지급 상한을 200만 원 이내로 정하는 학원법 시행규칙 개정안은 입법예고 중이다.</p><p>허용되는 관찰·면담 형식이라도 정답이 정해진 구술시험처럼 진행하면 학원법 위반으로 과태료 등 행정처분을 받을 수 있다. 학원법 시행령은 유아를 대상으로 모집·분반을 위한 시험이나 평가를 한 경우 1차 100만 원, 2차 200만 원, 3차 이상 300만 원의 과태료를 물릴 수 있도록 하며, 이는 시도 조례 개정 여부와 관계없이 바로 적용할 수 있다고 교육부는 설명했다.</p><p>교육부가 이미 배포한 해설서에 따르면 정규교육과정과 무관한 별도의 평가 절차를 운영하고 그 결과로 입학 여부를 정하는 행위도 금지된다. 정규교육과정과 연계한 사전 교육(오리엔테이션)은 할 수 있지만, 이를 근거로 입학을 거부하는 것은 허용되지 않는다.</p><p>‘4세 고시’ 금지와 관련한 조례 개정이 늦어지는 일부 시도교육청에는 교습정지·등록말소 등 행정처분 기준이 현장에서 차질 없이 적용되도록 조례 개정을 서두르라고 독려할 계획이다. 교육부는 시도교육청 담당자 간담회와 교육을 열어 점검 요령과 처분 사례를 공유하고, 학부모와 학원을 대상으로 한 안내도 강화한다. 운영상 미비점이 나타나면 사후관리와 제도 보완을 이어 가겠다는 방침이다.</p><p>강민규 교육부 영유아정책국장은 “유아 대상 레벨테스트 금지 제도가 현장에서 제대로 지켜질 수 있도록 시도교육청과 긴밀히 협력하겠다”며 “법 시행 취지에 맞게 아동의 건강한 성장을 보호하기 위한 노력을 계속해 나가겠다”고 밝혔다.</p>', '교육부가 10월 시행된 유아 대상 레벨테스트 금지 제도의 현장 안착을 위해 홍보와 12월~1월 집중 점검, 신고포상금 활용 방침을 밝혔다.', '/sites/thecaretimes/photos/ct-edu-4.webp', '2026-10-21T16:50:00+09:00'::timestamptz, array['레벨테스트', '학원법', '유아', '사교육', '교육부']::text[]),
  ('햇빛이음학교 태양광 설비 매년 검사…교육부·전기안전공사 협약', '<p>@@BYLINE@@&nbsp;교육부가 한국전기안전공사와 학교 태양광 설비의 안전 확보를 위한 업무협약을 맺는다. 교육부는 협약을 15일 한국전기안전공사 본사(전북 완주군)에서 체결하기로 했다고 14일 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-5.webp" alt="언덕에 설치된 태양광 패널"><p><em>▲ 태양광 발전설비 자료사진(2008년 6월 촬영한 충남 태안 태양광발전소를 일부 잘라 사용, 학교 시설이 아니며 이번 협약과 무관) / 사진: junilly(파노라미오), 위키미디어 공용(CC BY 3.0)</em></p><p>이번 협약은 교육부가 지난 2월 발표한 ‘햇빛이음학교’ 사업계획에 포함된 안전관리 강화 방안의 하나다. 현행 전기안전관리법에 따르면 태양광 설비는 4년마다 최소 1회 이상 한국전기안전공사의 검사를 받아야 하고, 현재 대부분의 학교는 4년 주기로 검사를 받는다. 이번 협약으로 햇빛이음학교는 매년 검사를 받을 수 있는 여건이 조성된다. 검사 비용은 연간 20만 원 안팎이다.</p><p>한국전기안전공사는 검사 수요 증가에 대비해 일정이 밀리지 않도록 미리 준비하고, 매년 검사 안내서를 보내 학교가 검사 시기를 놓치지 않도록 돕는다. 현재 법정검사 항목에는 없는 열화상 측정도 더해, 열화상 카메라로 육안으로는 확인할 수 없는 이상 징후를 점검한다. 화재 위험 징후가 있으면 미리 조치할 수 있게 돼 정기점검 성격의 법정검사가 ‘상시 예방관리형’으로 넓어지는 효과가 있다고 교육부는 설명했다.</p><p>검사 주기 단축은 우선 햇빛이음학교 사업 대상 학교에 적용한다. 이미 태양광 설비를 갖춘 학교로 넓힐지는 시도교육청과 학교의 의견 등을 종합해 추후 검토한다. 교육부는 한국전기안전공사의 전문성을 활용해 기술 지원뿐 아니라 안전관리 정보 제공과 학교 관계자 대상 전기안전관리 교육도 늘릴 계획이다.</p><p>최교진 교육부 장관은 “햇빛이음학교 사업을 통해 학교에 태양광 설비가 확대되는 만큼, 무엇보다 안전이 가장 중요하다”며 “이번 협약을 계기로 학교 태양광 설비의 안전관리 체계를 더욱 촘촘하게 다지고, 학교 현장의 부담을 최소화하면서도 안전을 강화할 수 있는 방안을 지속적으로 마련해 나가겠다”고 밝혔다.</p>', '교육부가 한국전기안전공사와 협약을 맺어 햇빛이음학교의 태양광 설비를 매년 검사하고 열화상 측정을 더하기로 했다.', '/sites/thecaretimes/photos/ct-edu-5.webp', '2026-10-22T11:05:00+09:00'::timestamptz, array['학교안전', '태양광', '햇빛이음학교', '한국전기안전공사', '교육부']::text[]),
  ('특성화 선도대학 33개교 선정…5년간 약 6,000억 원 지원', '<p>@@BYLINE@@&nbsp;교육부가 사립대학의 특성화에 5년간 약 6,000억 원을 지원하는 ‘2026년 특성화 선도대학 육성사업’ 선정평가 결과를 12일 발표했다. 일반대학 16곳과 전문대학 17곳, 모두 33개교가 뽑혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-6.webp" alt="연못 위 분수와 흰 기둥 건물이 보이는 대학 캠퍼스"><p><em>▲ 대학 캠퍼스 자료사진(2024년 4월 촬영, 이번 선정 대학과 무관) / 사진: HYH031277777, 위키미디어 공용(CC0)</em></p><p>이 사업은 학령인구 감소와 급속한 산업구조 변화에 대응해 사립대학이 중장기 발전계획과 국가·지역의 정책·산업 수요를 연계한 지속 가능한 특성화 모형을 만들도록 올해 새로 만들었다. 올해 ‘대학·전문대학 혁신지원사업’ 안에 특성화 지원금(인센티브)이 새로 반영됐다. 선정 대학에는 2026년부터 2030년까지 5년간 약 6,000억 원을 지원한다. 올해 지원 규모는 일반대학 850억 원(학교당 평균 50억 원), 전문대학 340억 원(학교당 평균 20억 원)이다.</p><p>선정 대학은 「지방대학 및 지역균형인재 육성에 관한 법률」 제17조에 따른 ‘특성화 지방대학’으로 지정돼 규제특례도 적용받는다. 교육부가 든 예시는 통합대학(일반대+전문대)의 전문학사 학위 수여, 비전임교원 공개채용 예외 적용, 교지·교사 임차범위 제한 규제 완화 등이다.</p><p>일반대학은 모두 비수도권 대학이고, 전문대학은 수도권과 비수도권 대학이 함께 선정됐다. 대학들은 반도체, 실물인공지능(피지컬AI), 항공 등 대학의 강점 분야나 국가 정책 방향, 지역 전략산업과 연계한 분야로 특성화 계획을 세웠다. 일반대학에서는 경운대(항공), 선문대(반도체), 광주대(돌봄·안전) 등이, 전문대학에서는 구미대(피지컬 AI), 전남과학대(반도체), 수원여자대(AI기반 통합돌봄) 등이 선정 대학에 포함됐다.</p><p>선정평가에서는 특성화 분야 선정의 타당성, 특성화 분야 교육과정 혁신성, 학생 진로·취업 지원체계의 구체성을 종합적으로 따졌다. 특히 교육 역량이 특성화 분야에 모이도록 비교우위 학과 중심의 역할 조정과 학과 재구조화 계획이 내실 있게 설계됐는지를 중점적으로 봤다.</p><p>대학들은 특성화 계획에 따라 2030학년도까지 3% 이상 정원을 줄이고, 특성화 분야 중심으로 대학 안 학과를 재구조화한다. 이 과정에서 축소되는 학과 학생의 학습권 보호 대책도 함께 마련한다. 교육부는 선정 결과를 대학에 통보한 뒤 이의신청 기간을 거쳐 지원 대상을 최종 확정한다. 이후 연차·중간평가 결과에 따라 사업비를 차등 지원하고, 사업 종료 뒤에도 최대 5년간 이행 실적을 해마다 점검한다.</p><p>최은옥 교육부 차관은 “이번 사업은 대학이 자율적인 구조개선을 통해 특성화 분야에 역량을 집중하여, 학생들에게 수준 높은 교육을 제공할 수 있는 기회가 될 것이다”라며 “사립대학이 특성화를 추진하여 경쟁력을 강화할 수 있도록, 재정 지원과 규제 완화로 뒷받침하겠다”고 말했다.</p>', '교육부가 반도체·피지컬AI·항공 등 강점 분야를 중심으로 일반대학 16곳, 전문대학 17곳을 특성화 선도대학으로 선정하고 5년간 약 6,000억 원을 지원한다.', '/sites/thecaretimes/photos/ct-edu-6.webp', '2026-10-26T10:30:00+09:00'::timestamptz, array['특성화선도대학', '사립대학', '전문대학', '대학혁신', '지역대학']::text[]),
  ('국제기능올림픽 입상자 40명 중 38명이 직업계고 출신', '<p>@@BYLINE@@&nbsp;올해 국제기능올림픽대회 입상자 40명 가운데 38명(95%)이 직업계고등학교 출신인 것으로 나타났다. 교육부는 27일 지난 9월 22~27일 중국 상하이에서 열린 제48회 국제기능올림픽대회 결과를 이같이 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-7.webp" alt="운동장 너머로 보이는 마이스터고 교사"><p><em>▲ 마이스터고 교사 자료사진(2019년 6월 촬영한 대전 소재 학교, 이번 입상자 출신 학교와 무관) / 사진: 이강철, 위키미디어 공용(CC BY-SA 4.0)</em></p><p>우리나라는 이번 대회에서 종합 2위를 했다. 금메달 4개, 은메달 14개, 동메달 6개, 우수상 16개를 땄다. 금메달 4개 중 3개, 은메달 14개 전부, 동메달 6개 중 5개, 우수상 16개 전부를 직업계고 출신 선수가 가져갔다.</p><p>8월 22~28일 인천에서 열린 제61회 전국기능경기대회에서도 입상자 384명 가운데 312명(81.2%)이 직업계고에 재학 중이거나 졸업한 학생이었다. 다만 이 수치는 출신 학교를 확인할 수 있는 경우만 집계한 것이다.</p><p>교육부는 국제대회 금메달 사례로 광전자기술 직종(동아마이스터고 졸업), 웹기술 직종(여수정보과학고 졸업), 산업제어 직종(영남공업고 졸업) 선수 3명을 소개했다. 이들은 학교 동아리 등에서 적성을 발견하고 2023년 전국기능경기대회 입상을 계기로 선발전을 거쳐 국가대표가 됐다. 졸업한 뒤에는 기업에 들어가 산업현장에서 실무 경험을 쌓으며 훈련을 이어 갔다고 교육부는 전했다.</p><p>교육부는 직업계고 학생이 졸업 뒤에도 현장에서 역량을 키워 숙련기술 인재로 자라도록 진로탐색부터 직무교육, 기업 취업 연계, 취업 후 성장까지 단계별 지원을 강화하고 있다고 밝혔다. 1·2학년에게는 기업 탐방과 연구과제(미니프로젝트) 수행 같은 직무성장 프로그램을, 3학년에게는 기업 수요에 맞춘 채용연계형 직무교육과정을 제공한다. 중앙취업지원센터를 통해 일자리를 발굴해 기업과 학생을 이어 주고, 졸업 후 취업한 학생이 안정적으로 자리 잡도록 취업연계 장려금도 지원한다. 미취업·진로 미결정 졸업생에게는 고졸자 후속지원 거점학교에서 취업역량 강화와 진로상담을 제공한다.</p><p>유지완 교육부 학교지원관은 “국제기능올림픽 국가대표의 90% 이상이 직업계고 출신이라는 점은, 청소년 시기부터 기술 관련 흥미와 적성을 발견하고 역량을 기르는 것이 중요함을 보여준다”라며 “교육부는 직업계고 기술인재들이 세계 수준의 손기술로 대체불가 기술강국 대한민국을 만들어 나갈 수 있도록 아낌없이 지원하겠다”고 밝혔다.</p>', '교육부는 제48회 국제기능올림픽대회에서 종합 2위를 한 가운데 입상자 40명 중 38명, 전국기능경기대회 입상자 384명 중 312명이 직업계고 출신이라고 밝혔다.', '/sites/thecaretimes/photos/ct-edu-7.webp', '2026-10-27T14:10:00+09:00'::timestamptz, array['직업계고', '국제기능올림픽', '직업교육', '마이스터고', '기능경기대회']::text[]),
  ('한국형 사회정서교육 우수사례 공모…11월 4일까지 접수', '<p>@@BYLINE@@&nbsp;교육부와 한국교육환경보호원이 학생 마음건강을 위한 ‘2026년 한국형 사회정서교육 우수사례 공모전’을 올해 처음 연다. 교육부는 22일 학교 현장에서 한국형 사회정서교육(K-SEL)을 실천한 우수사례를 발굴하고 퍼뜨리기 위한 공모전이라고 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-8.webp" alt="벤치와 나무가 있는 초등학교 운동장 쉼터"><p><em>▲ 초등학교 쉼터와 운동장 자료사진(2019년 9월 촬영) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>한국형 사회정서교육은 모든 학생을 대상으로 하는 보편적 마음건강 예방교육이다. 자기인식·관리, 소통·협력, 마음돌봄 등 학생이 긍정적인 마음을 키우고 정신건강을 증진하도록 돕는 것이 목적이다. 교육부는 국정과제인 ‘학생의 마음건강을 위한 다층적 지원체계 구축’의 이행 방안으로 2025년부터 전국 학교에 도입해 운영하고 있다. 초·중·고 교육과정 전반에 적용될 수 있도록 연간 6차시인 운영 시간을 2027년에는 17차시로 늘린다.</p><p>공모 대상은 전국 초·중·고·특수학교 소속 교원과 교육전문직이고, 주제는 학교 교육과정을 통한 한국형 사회정서교육 실천 사례다. 교과 연계, 창의적 체험활동 등에서 사회정서교육을 적용해 학생 마음건강 증진, 공동체 의식 함양, 학업성취 향상 등을 꾀한 실제 운영 사례가 대상이다.</p><p>접수는 10월 26일부터 11월 4일 오후 6시까지다. 서류 심사로 뽑은 10개 공모작을 대상으로 발표 심사를 거쳐 최종 순위를 정하고, 최종 수상자는 11월 말 발표할 예정이다. 최종 선정작에는 교육부 장관상과 상금을 주며, 우수사례는 사례집 발간과 성과 공유회로 학교 현장에 알린다.</p><p>교육부는 이와 별도로 사회정서교육 17차시용 교과연계 자료를 2027년 1월까지 에듀넷에 올리고, 선도교사 약 1,500명을 2027년 2월까지 양성할 계획이다.</p><p>김태경 교육부 학생건강안전정책국장은 “학생들이 급변하는 사회 속에서 정서적 안정감을 찾고 타인과 소통하는 힘을 기르는 것은 미래 교육의 가장 핵심적인 과제이다”라며 “이번 공모전을 통해 현장의 선생님들이 묵묵히 실천해 온 따뜻하고 창의적인 마음성장 교육 사례들이 널리 알려져, 학교 현장 전반으로 확산되기를 기대한다”고 밝혔다.</p>', '교육부와 한국교육환경보호원이 올해 처음 한국형 사회정서교육 우수사례 공모전을 열고 11월 4일까지 교원·교육전문직의 사례를 접수한다.', '/sites/thecaretimes/photos/ct-edu-8.webp', '2026-10-23T09:40:00+09:00'::timestamptz, array['사회정서교육', '마음건강', '학생복지', '공모전', '교육부']::text[]),
  ('제19회 전국 학교스포츠클럽 축전 개막…수능 뒤 고3 종목 추가', '<p>@@BYLINE@@&nbsp;제19회 전국 학교스포츠클럽 축전이 10월 23일부터 12월 13일까지 전국 각지에서 21개 종목으로 나뉘어 열린다. 교육부는 시도교육청, 학교체육진흥회와 함께 이 대회를 개최한다고 22일 밝혔다.</p><img src="/sites/thecaretimes/photos/ct-edu-9.webp" alt="아파트 단지 옆 학교 운동장"><p><em>▲ 학교 운동장 자료사진(2019년 9월 촬영, 대회 장소와 무관) / 사진: 고려, 위키미디어 공용(CC BY 4.0)</em></p><p>2008년 처음 열린 학교스포츠클럽 축전은 올해 19회째다. 시도교육청 예선을 거쳐 뽑힌 전국 초·중·고등학교 학교스포츠클럽 소속 학생과 지도교사 2만여 명이 ‘함께 한 땀방울, 하나 된 열정!’이라는 표어 아래 기량을 겨룬다. 예선을 통과한 학생들은 10월 23일부터 11월 15일까지 4주 동안 서울, 충북 제천, 경남 김해 등에서 열리는 배드민턴, 축구, 탁구, 농구, 줄넘기, 배구 등 19개 종목에 참가한다.</p><p>이번 축전부터는 학업 부담으로 참여가 어려웠던 고등학교 3학년 학생을 위해 수능 뒤인 12월 12~13일 전북 익산에서 남고생 배구와 여고생 배드민턴 경기를 추가로 연다. 교육부는 학업 스트레스를 풀고 고교 생활을 뜻깊게 마무리하도록 돕기 위한 것이라고 설명했다. 종목별 일정과 경기 결과는 학교스포츠클럽포털에서 확인할 수 있다.</p><p>경기 외에 지역 문화·역사 탐방, 스포츠 기술 챌린지(예: 3점 슛 도전), 참가학교 응원 전시 같은 부대행사도 마련한다. 교육부는 올바른 응원 문화를 위한 교육자료를 미리 시도교육청에 배부해 학교에서 활용하도록 안내했고, ‘올바른 경기 문화 실천 및 확산을 위한 사회관계망서비스(SNS) 도전 잇기(챌린지)’도 함께 진행한다.</p><p>유지완 교육부 학교지원관은 “학생들의 체력 증진과 바른 인성 함양에 기여해 온 전국학교스포츠클럽 축전이 올해 고3 학생까지 아우르는 진정한 스포츠 축제로 거듭나기를 기대한다”라며 “학창 시절의 스포츠 경험이 평생의 건강한 습관이자 삶의 활력이 될 수 있도록, 학교체육 지원을 더욱 강화하겠다”고 밝혔다.</p>', '교육부는 학교스포츠클럽 학생과 지도교사 2만여 명이 참가하는 제19회 전국 학교스포츠클럽 축전을 10월 23일부터 12월 13일까지 연다고 밝혔다.', '/sites/thecaretimes/photos/ct-edu-9.webp', '2026-10-23T15:25:00+09:00'::timestamptz, array['학교스포츠클럽', '학교체육', '고3', '학생건강', '교육부']::text[]),
  ('등록금심의위원회 제도 개선…시행령·규칙 12월 7일까지 입법예고', '<p>@@BYLINE@@&nbsp;교육부가 대학 등록금심의위원회 제도를 손질하는 「고등교육법 시행령」과 「대학 등록금에 관한 규칙」 일부개정령안을 27일 입법예고했다. 입법예고 기간은 12월 7일까지 41일이다.</p><img src="/sites/thecaretimes/photos/ct-edu-10.webp" alt="건물 앞에 벚꽃이 핀 대학 캠퍼스"><p><em>▲ 대학 캠퍼스 자료사진(2026년 4월 촬영, 학생이 보이는 아래쪽을 잘라 사용) / 사진: Fengychen, 위키미디어 공용(CC BY-SA 4.0)</em></p><p>등록금심의위원회는 고등교육법 제11조에 따라 각 학교의 등록금을 정하기 위해 교직원, 학생, 관련 전문가 등으로 꾸리는 기구다. 교육부는 지난해 ‘대학 등록금 규제 합리화’ 조치 이후 대학별 등록금심의위원회의 기능과 역할이 커진 점을 반영했다고 밝혔다. 총학생회단체 간담회와 위원(학생·교직원·전문가 등) 면담으로 받은 의견을 바탕으로 개정안을 마련했다고 한다.</p><p>시행령 개정안에 따르면 등록금심의위원회는 등록금 산정에 필요한 경우 학교의 장에게 ‘등록금 인상에 따른 수입 증가 시 연계 지출 계획’ 자료를 요청할 수 있다. 위원들이 등록금 책정 이유를 더 분명히 파악하도록 하기 위한 것이다. 회의록은 작성한 뒤 공개하기 전에 위원의 확인을 거치도록 해 의사결정 과정의 투명성을 높인다.</p><p>「대학 등록금에 관한 규칙」 개정안에는 전문가 위원의 임기를 2년 범위에서 정하고 한 차례만 연임할 수 있게 하는 규정이 들어갔다. 학생 위원은 사실상 1년 단위로 바뀌는 반면 전문가 위원은 오래 맡을 수 있는 문제를 해소해 위원 간 논의가 균형 있게 이뤄지도록 하려는 것이다. 또 후속 조치가 필요한 의결 사항은 학교의 장이 조치 계획을 세워 등록금심의위원회에 보고하도록 했다. 현행 법령에는 의결 사항의 이행 여부를 공식적으로 확인하는 절차가 없다는 지적을 반영한 것이다.</p><p>국가장학금 등으로 저소득층 학비 지원이 강화된 점을 고려해 교내장학금(등록금 감면) 편성 기준도 정비한다. 현행 규칙은 대학이 전체 등록금의 10%를 면제·감액하되 그중 30%를 ‘경제적 사정이 곤란한 학생’에게 편성하도록 한다. 개정안은 이 30% 대상자를 경제적 사정 곤란자, 세 자녀 이상 양육 가정의 자녀, 장애인, 학교의 장이 우선적 학자금 지원이 필요하다고 인정하는 사람으로 넓힌다.</p><p>교육부는 입법예고 기간에 추가 의견을 받은 뒤 연내 두 법령을 개정·공포할 계획이다. 의견은 국민참여입법센터를 통해 온라인으로 내거나 교육부에 서면으로 제출할 수 있다.</p>', '교육부가 등록금 산정 근거자료 요청 범위 확대, 회의록 공개 전 위원 확인, 전문가 위원 임기 제한 등을 담은 등록금심의위원회 개선안을 입법예고했다.', '/sites/thecaretimes/photos/ct-edu-10.webp', '2026-10-27T17:35:00+09:00'::timestamptz, array['대학등록금', '등록금심의위원회', '고등교육법', '입법예고', '교내장학금']::text[])
) as v(title, body, excerpt, thumb, published_at, tags)
join categories c on c.outlet_id = ctx.outlet_id and c.name = '교육'
where ctx.author_id is not null
  and not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

-- 기자명 김경석 고정 + 'AI 메모'(확인할 점·원문 주소·이용 조건) (해당 칸이 없는 DB는 건너뛴다)
do $edu$
begin
  -- 작성 계정 이름이 김경석이 아니면 기사 기자명만 김경석으로 (article-manage.sql 의 byline 칸)
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'byline') then
    update articles a set byline = '김경석'
    from outlets o, profiles p, (values
      ('수능 11월 19일 시행…1,312개 시험장서 55만여 명 응시'),
      ('어린이집·유치원 입소·입학 신청 11월 2일 시작…‘찜하기’ 도입'),
      ('틈새돌봄 운영 기관, QR코드로 찾는다…소아과·육아센터에 포스터'),
      ('유아 레벨테스트 금지 제도 점검 강화…12월부터 집중 점검'),
      ('햇빛이음학교 태양광 설비 매년 검사…교육부·전기안전공사 협약'),
      ('특성화 선도대학 33개교 선정…5년간 약 6,000억 원 지원'),
      ('국제기능올림픽 입상자 40명 중 38명이 직업계고 출신'),
      ('한국형 사회정서교육 우수사례 공모…11월 4일까지 접수'),
      ('제19회 전국 학교스포츠클럽 축전 개막…수능 뒤 고3 종목 추가'),
      ('등록금심의위원회 제도 개선…시행령·규칙 12월 7일까지 입법예고')
    ) as v(title)
    where a.outlet_id = o.id and o.domain = 'thecaretimes.net' and a.title = v.title and p.id = a.author_id
      and a.status = 'in_review' and trim(coalesce(p.full_name, '')) <> '김경석' and a.byline is distinct from '김경석';
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'articles' and column_name = 'ai_notes') then
    update articles a set ai_notes = v.notes
    from outlets o, (values
  ('수능 11월 19일 시행…1,312개 시험장서 55만여 명 응시', '• 확인할 점: 시험장 수(1,312개)·응시 예정자(551,864명)·시험 시각은 10월 20일 보도자료 기준이며 이후 달라질 수 있다. 영어 듣기평가 시각(13:10~13:35)과 종료 시각(17:45, 중증 시각장애 21:48)을 원문과 대조할 것.
• 확인할 점: 사진은 수능 현장이 아니라 2018학년도 수능 수험생용 사인펜·샤프를 찍은 자료사진(2017.11.23. 촬영)이다. 펜에 ‘2018학년도’ 문구가 보여 캡션에 올해 시험 장면이 아님을 밝혔다.
• 확인할 점: 수험생 유의사항은 원문에서 ‘추후 별도 안내 예정’이라고 해 쓰지 않았다. 담당 공무원 이름·연락처는 쓰지 않았다.
